; Hi-res text map: Conquests of Camelot (SCI0), Korean UTF-8 translation.
;
; Picked up on its own when the game's language is Korean and no map is
; configured; or name it: hires_text_map=data:hires_text/maps/camelot-ko.map
;
; The status line, the parser line and the menus (the default face, font 0)
; in NanumGothic Bold; the dialogue and narration fonts (1, 4, 103) and the
; outlined title font (104) in Gowun Batang Bold. Latin text, digits and
; punctuation are drawn by the same face as the Korean, on the same baseline,
; and advance by the face's own widths - so an English word in a Korean
; sentence does not fall back to the game's 8 px font. This is what the DOS
; pack's baked CAMKO.MAP does with its bitmap faces.
;
; blend=auto anti-aliases the faces on a true-colour screen.
[map]
version=2

[render]
scale=2
blend=auto

[fonts]
ko=data:hires_text/fonts/nanumgothic/NanumGothic-Bold.ttf
batang=data:hires_text/fonts/gowunbatang/GowunBatang-Bold.ttf

[font]
face=ko
shift=0
range.basic-latin=same
advance.basic-latin=font

[font.0]
face=ko

[font.1]
face=batang
size=18

[font.4]
face=batang
size=18

[font.103]
face=batang
size=18

[font.104]
face=batang
size=18
